import React from "react";
import { apiFetch } from "./api";
import { formatGhc } from "./money";
import { h } from "./h";

/**
 * @param {string | null | undefined} accessToken
 * @param {{ type: string, productId?: string, meta?: Record<string, unknown> }} payload
 */
export function trackVendorAnalyticsEvent(accessToken, payload) {
  if (!accessToken || !payload?.type) return;
  void apiFetch("/api/vendor/analytics/events", {
    method: "POST",
    headers: { Authorization: `Bearer ${accessToken}` },
    json: payload
  }).catch(() => {});
}

const EVENT_COLORS = {
  analytics_view: "rgb(56 189 248)",
  dashboard_view: "rgb(129 140 248)",
  products_list_view: "rgb(52 211 153)",
  orders_view: "rgb(251 191 36)",
  product_edit_view: "rgb(244 114 182)",
  order_status_update: "rgb(148 163 184)"
};

/** @param {{ daily: Array<{ date: string; revenue: number; orderCount: number; eventCounts?: Record<string, number> }> }} props */
export function VendorRevenueLineChart({ daily }) {
  const w = 880;
  const h = 240;
  const padX = 36;
  const padY = 28;
  const vals = (daily || []).map((d) => Number(d.revenue) || 0);
  const max = Math.max(...vals, 1);
  const n = Math.max((daily || []).length, 1);
  const innerW = w - padX * 2;
  const innerH = h - padY * 2;
  const step = n > 1 ? innerW / (n - 1) : 0;
  const pts = (daily || []).map((d, i) => {
    const x = padX + i * step;
    const y = padY + innerH * (1 - (Number(d.revenue) || 0) / max);
    return `${x},${y}`;
  });
  const points = pts.join(" ");
  const gridY = [0, 0.25, 0.5, 0.75, 1].map((t) => {
    const y = padY + innerH * (1 - t);
    return h("line", {
      key: `g-${t}`,
      x1: padX,
      x2: w - padX,
      y1: y,
      y2: y,
      stroke: "rgba(148,163,184,0.25)",
      strokeWidth: 1
    });
  });
  const xLabels = (daily || []).map((d, i) =>
    i % Math.ceil(n / 6) === 0 || i === n - 1
      ? h(
          "text",
          {
            key: `xl-${d.date}`,
            x: padX + i * step,
            y: h - 6,
            fontSize: 10,
            fill: "rgb(148 163 184)",
            textAnchor: "middle"
          },
          d.date.slice(5)
        )
      : null
  );
  return h("div", { className: "w-full overflow-x-auto" }, [
    h("svg", { key: "svg", viewBox: `0 0 ${w} ${h}`, className: "h-60 w-full min-w-[640px]", role: "img", "aria-label": "Revenue by day" }, [
      ...gridY,
      h("polyline", {
        key: "line",
        fill: "none",
        stroke: "rgb(56 189 248)",
        strokeWidth: 2.5,
        strokeLinejoin: "round",
        strokeLinecap: "round",
        points
      }),
      ...(daily || []).map((d, i) => {
        const x = padX + i * step;
        const y = padY + innerH * (1 - (Number(d.revenue) || 0) / max);
        return h("circle", {
          key: `c-${d.date}`,
          cx: x,
          cy: y,
          r: 3,
          fill: "rgb(125 211 252)",
          stroke: "rgb(15 23 42)",
          strokeWidth: 1
        });
      }),
      ...xLabels.filter(Boolean)
    ]),
    h("p", { key: "cap", className: "mt-2 text-center text-xs text-slate-500 dark:text-slate-400" }, "Your seller proceeds by order date (UTC)")
  ]);
}

/** @param {{ daily: Array<{ date: string; orderCount: number }> }} props */
export function VendorOrdersBarChart({ daily }) {
  const max = Math.max(...(daily || []).map((d) => Number(d.orderCount) || 0), 1);
  const barMaxPx = 168;
  return h(
    "div",
    { className: "flex h-56 items-end gap-1 overflow-x-auto rounded-2xl border border-white/10 bg-night-900/30 p-3 pb-8" },
    (daily || []).map((d) => {
      const c = Number(d.orderCount) || 0;
      const hPx = Math.max(4, Math.round((c / max) * barMaxPx));
      return h(
        "div",
        { key: d.date, className: "flex min-w-[10px] flex-1 flex-col items-center justify-end gap-1" },
        [
          h("div", {
            key: "bar",
            className: "w-full max-w-7 rounded-t-lg bg-gradient-to-t from-indigo-600 to-sky-400",
            style: { height: `${hPx}px` },
            title: `${d.date}: ${c} order(s)`
          }),
          h("span", { key: "lb", className: "text-[9px] text-slate-500 dark:text-slate-400" }, d.date.slice(8))
        ]
      );
    })
  );
}

/** @param {{ daily: Array<{ date: string; eventCounts?: Record<string, number> }>, maxDays?: number }} props */
export function VendorEventsStackedBars({ daily, maxDays = 14 }) {
  const slice = (daily || []).slice(-maxDays);
  const types = Object.keys(EVENT_COLORS);
  return h("div", { className: "space-y-2" }, [
    h("div", { key: "legend", className: "flex flex-wrap gap-2 text-[10px] text-slate-600 dark:text-slate-300" }, [
      ...types.map((t) =>
        h("span", { key: t, className: "inline-flex items-center gap-1 rounded-full border border-white/10 px-2 py-0.5" }, [
          h("span", { key: "sw", className: "h-2 w-2 rounded-full", style: { backgroundColor: EVENT_COLORS[t] || "#94a3b8" } }),
          t.replace(/_/g, " ")
        ])
      )
    ]),
    ...slice.map((d) => {
      const counts = types.map((t) => ({ t, c: Number(d.eventCounts?.[t]) || 0 }));
      const sum = counts.reduce((s, x) => s + x.c, 0);
      const total = sum || 0;
      return h("div", { key: d.date, className: "flex items-center gap-2 text-xs" }, [
        h("span", { className: "w-14 shrink-0 font-mono text-slate-500 dark:text-slate-400" }, d.date.slice(5)),
        h(
          "div",
          {
            className: "flex h-3 flex-1 overflow-hidden rounded-full bg-white/10 dark:bg-night-800/80",
            title: total ? `${total} events` : "No events"
          },
          counts
            .filter((x) => x.c > 0)
            .map((x) =>
              h("div", {
                key: x.t,
                style: {
                  width: `${(x.c / (total || 1)) * 100}%`,
                  backgroundColor: EVENT_COLORS[x.t] || "#64748b"
                },
                title: `${x.t}: ${x.c}`
              })
            )
        ),
        h("span", { className: "w-6 shrink-0 text-right text-slate-500" }, String(total))
      ]);
    })
  ]);
}
